import { test, expect } from '@playwright/test';

test.describe('Accessibility - Focus Indicators', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should have focus indicator on button', async ({ page }) => {
    const button = page.getByRole('button', { name: /submit/i });
    await button.focus();
    const isFocused = await button.evaluate(el => document.activeElement === el);
    expect(isFocused).toBe(true);
    await expect(button).toHaveCSS('outline', /solid/); // Adjust the CSS property as needed
  });

  test('should have focus indicator on link', async ({ page }) => {
    const link = page.getByRole('link', { name: /learn more/i });
    await link.focus();
    const isFocused = await link.evaluate(el => document.activeElement === el);
    expect(isFocused).toBe(true);
    await expect(link).toHaveCSS('outline', /solid/); // Adjust the CSS property as needed
  });
});
